    "questionHtml": "<strong>Perhatikan kalimat yang cacat struktur sintaksisnya berikut!</strong><br><br><em>'Meskipun data statistik menunjukkan bahwa penurunan angka kemiskinan telah terjadi di berbagai wilayah perdesaan, namun apabila tidak diimbangi dengan pemerataan infrastruktur logistik, sehingga kesejahteraan masyarakat belum dapat terdistribusi secara optimal.'</em><br><br>Penyebab utama kalimat di atas tidak memiliki induk kalimat (kalimat mandiri) adalah...",
