    "type": "matrix",
    "questionHtml": "<strong>Cermati tiga pernyataan dalam forum perdebatan publik berikut!</strong><br><br>Tentukan apakah klasifikasi kesesatan berpikir (<em>logical fallacy</em>) pada pernyataan-pernyataan di bawah ini <strong>BENAR</strong> atau <strong>SALAH</strong>!",
